%dw 2.0 import firstWith from dw::core::Arrays output application/json
// Rocketlane choice fields (loaded by the two /fields requests at the start of the When branch) var choiceFields = (vars.rlSingleChoice.data default []) ++ (vars.rlMultiChoice.data default [])
fun fieldId(name) = p("secure::rocketlaneFields." ++ name) as Number fun blank(v) = v == null or trim(v as String) == ""
fun toText(v) = if (blank(v)) null else v as String fun toPlainText(v) = if (blank(v)) null else trim((((v as String) replace /<[^>]*>/ with " ") replace /&nbsp;/ with " ") replace /&amp;/ with "&") fun toDate(v) = if (blank(v)) null else (v as String)[0 to 9] fun toYesNo(v) = if (v == null) null else ((v as String) == "true")
// Choice values are sent as Rocketlane option numbers, matched by label (case-insensitive) fun optionsOf(name) = (choiceFields firstWith ((f) -> f.fieldId == fieldId(name))).fieldOptions default [] fun optionValue(name, label) = (optionsOf(name) firstWith ((o) -> lower(trim(o.optionLabel)) == lower(trim(label)))).optionValue fun oneOf(name, v) = if (blank(v)) null else optionValue(name, v as String) fun manyOf(name, v) = if (blank(v)) null else (((v as String) splitBy ";") map optionValue(name, $)) filter ($ != null) // Rocketlane country/state options look like "United States (US)" / "Alabama (AL)" fun countryOption(code) = if (blank(code)) null else (optionsOf("billingCountryCode") firstWith ((o) -> o.optionLabel endsWith ("(" ++ code ++ ")"))).optionValue fun stateOption(stateName, code) = if (blank(code)) null else (optionsOf("billingStateProvinceCode") firstWith ((o) -> lower(o.optionLabel) == lower((stateName default "") ++ " (" ++ code ++ ")"))).optionValue
// Empty values (and choice values with no matching Rocketlane option) are left out fun rlField(name, value) = if (value == null or value == []) null else { fieldId: fieldId(name), fieldValue: value } --- { projectName: payload.Name, owner: { userId: p('secure::rocketlane.defaultOwnerId') as Number }, customer: { companyName: payload.Account__r.Name }, externalReferenceId: payload.Id, visibility: "EVERYONE", autoCreateCompany: true, (startDate: toDate(payload.StartDate__c)) if (not blank(payload.StartDate__c)), fields: [ rlField("closeDate", toDate(payload.CloseDate__c)), rlField("businessUnit", oneOf("businessUnit", payload.BusinessUnit__c)), rlField("otherLegacyDatabase", toText(payload.Opportunity__r.Other_Legacy_Database__c)), rlField("implementationTimelineDeadline", toPlainText(payload.ImplementationTimelineDeadline__c)), rlField("federatedSpoke", toYesNo(payload.Account__r.Federated_Partner_Spoke__c)), rlField("purchasedWebsiteBuild", toYesNo(payload.Account__r.Purchased_Website_Build__c)), rlField("websiteBuildStatus", toText(payload.Account__r.Website_Build_Status__c)), rlField("implementationTimelineDetails", toPlainText(payload.Opportunity__r.ImplementationTimeDeadlines__c)), rlField("accountProduct", toText(payload.Account__r.Account_Product__c)), rlField("leadSource", oneOf("leadSource", payload.Opportunity__r.LeadSource)), rlField("isTestAccount", toYesNo(payload.IsTestAccount__c)), rlField("templateCopyUrl", toText(payload.TemplateCopyURL__c)), rlField("implementationPriority", oneOf("implementationPriority", payload.Opportunity__r.Implementation_Priority__c)), rlField("prioritiesForInitialSetUp", manyOf("prioritiesForInitialSetUp", payload.Opportunity__r.Priorities_for_Initial_Set_Up__c)), rlField("implementationProductCodes", toText(payload.Implementation_Products__c)), rlField("implementationTypeText", toText(payload.Implementation_Type__c)), rlField("sfId", toText(payload.Account__r.x18__c)), rlField("neonCrmInstanceCreatedDate", toDate(payload.Neon_CRM_Instance_Created_Date__c)), rlField("neoncrmModules", toText(payload.Opportunity__r.NeonCRM_Modules__c)), rlField("timelineRequest", oneOf("timelineRequest", payload.Opportunity__r.Level_of_Priority__c)), rlField("primaryContactName", toText(payload.Account__r.PrimaryContactName__c)), rlField("primaryContactEmail", toText(payload.Account__r.Primary_Contact_Email__c)), rlField("technicalContactName", toText(payload.Account__r.TechnicalContactName__c)), rlField("technicalContactEmail", toText(payload.Account__r.TechnicalContactEmail__c)), rlField("currentAccountingSystem", oneOf("currentAccountingSystem", payload.Opportunity__r.Current_Accounting_System__c)), rlField("addOnNotes", toText(payload.Opportunity__r.Special_Pricing_or_Add_On_Notes__c)), rlField("targetLaunchDate", toDate(payload.Opportunity__r.Estimated_Launch_Date__c)), rlField("trialUrl", toText(payload.Opportunity__r.TrialURL__c)), rlField("opportunityCloseDate", toDate(payload.Opportunity__r.CloseDate)), rlField("startPurchaseDate", toDate(payload.CreatedDate)), rlField("neoncrmInstanceName", toText(payload.ProductionInstanceName__c)), rlField("purchasedNcrmImplementation", toYesNo(payload.Account__r.Purchased_NCRM_Implementation__c)), rlField("neonPayProcessor", oneOf("neonPayProcessor", payload.Opportunity__r.Neon_Pay_Processor__c)), rlField("partner", toYesNo(payload.Opportunity__r.External_Consultant__c)), rlField("partnerAccount", toText(payload.Opportunity__r.PartnerAccount__r.Name)), rlField("partnerName", toText(payload.Opportunity__r.Partner_Name__c)), rlField("partnerEmail", toText(payload.Opportunity__r.Partner_Email__c)), rlField("partnerPhoneNumber", toText(payload.Opportunity__r.Partner_Phone_Number__c)), rlField("website", toText(payload.Opportunity__r.Website__c)), rlField("neonWebsitesPackage", manyOf("neonWebsitesPackage", payload.Account__r.Neon_Websites_Package__c)), rlField("websiteLaunchDate", toDate(payload.Account__r.Website_Launch_Date__c)), rlField("websiteAbandonedDate", toDate(payload.Account__r.Website_Abandoned_Date__c)), rlField("implementationProduct", oneOf("implementationProduct", payload.ProjectType__c)), rlField("ae", toText(payload.Account__r.Account_Owner_Text__c)), rlField("timezone", toText(payload.Account__r.Timezone__c)), rlField("instanceLogin", toText(payload.Instance_Login__c)), rlField("billingStreet", toText(payload.Account__r.BillingStreet)), rlField("billingCity", toText(payload.Account__r.BillingCity)), rlField("billingStateProvince", toText(payload.Account__r.BillingState)), rlField("billingZipPostalCode", toText(payload.Account__r.BillingPostalCode)), rlField("billingCountry", toText(payload.Account__r.BillingCountry)), rlField("billingCountryCode", countryOption(payload.Account__r.BillingCountryCode)), rlField("billingStateProvinceCode", stateOption(payload.Account__r.BillingState, payload.Account__r.BillingStateCode)), rlField("accountProducts", toText(payload.Opportunity__r.ProductRollup__c)), rlField("ncrmImplementationCompleteDate", toDate(payload.Account__r.NCRM_Implementation_Complete_Date__c)), rlField("ncrmImplementationStatus", toText(payload.Account__r.NCRM_Implementation_Status__c)), rlField("ncrmImplementationIncompleteDate", toDate(payload.Account__r.NCRM_Implementation_Incomplete_Date__c)), rlField("artsPeopleImplementationIncompleteDate", toDate(payload.Account__r.Arts_People_Implementation_Incomplete_Da__c)), rlField("rallyboundImplementationIncompleteDate", toDate(payload.Account__r.Rallybound_Implementation_Incomplete_Dat__c)), rlField("ippInterest", oneOf("ippInterest", payload.Opportunity__r.In_Person_Payments_Interest__c)), rlField("artsPeopleImplementationStatus", toText(payload.Account__r.Arts_People_Implementation_Status__c)), rlField("artsPeopleImplementationCompleteDate", toDate(payload.Account__r.Arts_People_Implementation_Complete_Date__c)), rlField("purchasedRallyboundImplementation", toYesNo(payload.Account__r.Purchased_Rallybound_Implementation__c)), rlField("rallyboundImplementationCompleteDate", toDate(payload.Account__r.Rallybound_Implementation_Complete_Date__c)), rlField("rallyboundImplementationStatus", toText(payload.Account__r.Rallybound_Implementation_Status__c)) ] filter ($ != null) }
